bool number(const var& v,double low,double high,bool integer=false){if(!(v.isInt()||v.isInt64()||v.isDouble()))return false;double n=(double)v;return std::isfinite(n)&&n>=low&&n<=high&&(!integer||n==std::floor(n));}
bool text(const var& v,int limit){if(!v.isString()||v.toString().trim().isEmpty()||v.toString().length()>limit)return false;for(auto c:v.toString())if(c<32||c==127)return false;return true;}
bool keys(const var& v,std::initializer_list<const char*> names){if(!v.isObject())return false;for(const auto& field:v.getDynamicObject()->getProperties()){bool found=false;for(auto name:names)found|=field.name.toString()==name;if(!found)return false;}return true;}
Result fail(const String& message){return Result::fail(message);}
bool index(const var& v,size_t count){return count>0&&number(v,0,(double)count-1,true);}
Result readAutomationPoints(const var& value,double length,std::vector<AutomationPoint>& output){
    if(!value.isArray()||value.getArray()->size()<2||value.getArray()->size()>maxAutomationPoints)return fail("Use 2-256 automation points.");
    Clip c;c.length=length;
double previous=-1;for(const auto& p:*value.getArray()){if(!keys(p,{"beat","value","hold","curve","tension"})||!number(p["beat"],0,c.length)||(double)p["beat"]<=previous||!number(p["value"],0,1)||(p.hasProperty("hold")&&!p["hold"].isBool()))return fail("Automation points need increasing beats and normalized values.");previous=(double)p["beat"];AutomationPoint point{previous,(float)(double)p["value"],(bool)p["hold"]};if(p.hasProperty("curve")){if(!number(p["curve"],0,3,true))return fail("Invalid automation curve.");point.curve=(AutomationCurve)(int)p["curve"];}if(p.hasProperty("tension")){if(!number(p["tension"],-1,1))return fail("Invalid automation tension.");point.tension=(float)(double)p["tension"];}c.points.push_back(point);}if(c.points.front().beat!=0||c.points.back().beat!=c.length)return fail("Automation must include both endpoints.");output=std::move(c.points);return Result::ok();}
bool instrument(const String& name,Instrument& output){const char* names[]={"kick","snare","hat","clap","open_hat","bass","pad","lead","sample","analog","fm","wavetable","additive","physical"};for(int i=0;i<instrumentCount;++i)if(name==names[i]&&i!=8){output=(Instrument)i;return true;}return false;}
Result effectSettings(const var& effects,Track::Mixer& destination){
    if(!keys(effects,{"eq","compressor","reverb","chorus","flanger","phaser","stereo","order"}))return fail("Unknown control effect.");
    auto fx=destination;
    if(effects.hasProperty("order")){auto valid=effectOrderFromJson(effects["order"],fx.order);if(valid.failed())return valid;}
    struct Setting {const char* name;float* value;double low,high;};
    for(auto key:{"eq","compressor","reverb"})if(effects.hasProperty(key)){
        auto p=effects[key];bool eq=String(key)=="eq",comp=String(key)=="compressor";
        if(eq?!keys(p,{"enabled","low","mid","high"}):comp?!keys(p,{"enabled","threshold","ratio","attack","release","makeup","mode","range","hysteresis","hold","knee"}):!keys(p,{"enabled","mix","room","damping"}))return fail("Invalid effect settings.");
        bool enabled=true;if(p.hasProperty("enabled")){if(!p["enabled"].isBool())return fail("Effect enabled must be boolean.");enabled=(bool)p["enabled"];}
        if(eq){fx.eq=enabled;for(auto value:{Setting{"low",&fx.low,-18,18},Setting{"mid",&fx.mid,-18,18},Setting{"high",&fx.high,-18,18}})if(p.hasProperty(value.name)){if(!number(p[value.name],value.low,value.high))return fail("Invalid EQ gain.");*value.value=(float)(double)p[value.name];}}
        else if(comp){fx.compressor=enabled;if(p.hasProperty("mode")){if(!p["mode"].isString())return fail("Dynamics mode must be a string.");const char* modes[]={"compressor","limiter","gate","expander"};int selected=-1;for(int i=0;i<4;++i)if(p["mode"].toString()==modes[i])selected=i;if(selected<0)return fail("Unknown dynamics mode.");fx.dynamics.mode=(DynamicsMode)selected;}for(auto value:{Setting{"range",&fx.dynamics.range,0,96},Setting{"hysteresis",&fx.dynamics.hysteresis,0,24},Setting{"hold",&fx.dynamics.hold,0,1000},Setting{"knee",&fx.dynamics.knee,0,24}})if(p.hasProperty(value.name)){if(!number(p[value.name],value.low,value.high))return fail("Invalid dynamics option.");*value.value=(float)(double)p[value.name];}for(auto value:{Setting{"threshold",&fx.threshold,-60,0},Setting{"ratio",&fx.ratio,1,20},Setting{"attack",&fx.compAttack,.1,100},Setting{"release",&fx.compRelease,5,1000},Setting{"makeup",&fx.makeup,-12,24}})if(p.hasProperty(value.name)){if(!number(p[value.name],value.low,value.high))return fail("Invalid compressor parameter.");*value.value=(float)(double)p[value.name];}}
        else{fx.reverb=enabled;for(auto value:{Setting{"mix",&fx.reverbMix,0,1},Setting{"room",&fx.room,0,1},Setting{"damping",&fx.damping,0,1}})if(p.hasProperty(value.name)){if(!number(p[value.name],value.low,value.high))return fail("Invalid reverb parameter.");*value.value=(float)(double)p[value.name];}}
    }
    for(auto key:{"chorus","flanger","phaser","stereo"})if(effects.hasProperty(key)){
        const auto& p=effects[key];if(!p.isObject())return fail("Invalid effect object.");String kind(key);
        auto settings=kind=="chorus"?chorusToJson(fx.chorus):kind=="stereo"?stereoToJson(fx.stereo):modulationToJson(kind=="flanger"?fx.flanger:fx.phaser);
        settings.getDynamicObject()->setProperty("enabled",true);for(const auto& field:p.getDynamicObject()->getProperties()){if(!settings.hasProperty(field.name))return fail("Unknown effect parameter.");settings.getDynamicObject()->setProperty(field.name,field.value);}
        auto valid=kind=="chorus"?chorusFromJson(settings,fx.chorus):kind=="stereo"?stereoFromJson(settings,fx.stereo):modulationFromJson(settings,kind=="flanger"?ModulationKind::flanger:ModulationKind::phaser,kind=="flanger"?fx.flanger:fx.phaser);if(valid.failed())return valid;
    }
    destination=std::move(fx);return Result::ok();
}
Result trackSettings(const var& op,Track& t){
    for(auto key:{"mute","solo"})if(op.hasProperty(key)){if(!op[key].isBool())return fail("Mute and solo require booleans.");if(String(key)=="mute")t.mute=(bool)op[key];else t.solo=(bool)op[key];}
    if(op.hasProperty("name")){if(!text(op["name"],80))return fail("Track name must contain 1-80 printable characters.");t.name=op["name"].toString();}
    if(op.hasProperty("instrument")){if(t.isBus||!op["instrument"].isString()||!instrument(op["instrument"].toString(),t.instrument))return fail("Choose a built-in instrument; buses keep their identity.");t.samplePath.clear();}
    if(op.hasProperty("preset")){if(!op["preset"].isString())return fail("Preset must be a factory sound name.");auto it=std::find_if(factorySynthPresets().begin(),factorySynthPresets().end(),[&](const SynthPreset& p){return p.name==op["preset"].toString();});if(it==factorySynthPresets().end()||t.isBus)return fail("Factory sound is unavailable for this track.");if(op.hasProperty("instrument")&&t.instrument!=it->instrument)return fail("Preset and instrument do not match.");t.instrument=it->instrument;t.synth=it->patch;t.attack=it->attack;t.release=it->release;t.soundName=it->name;t.samplePath.clear();}
    if(op.hasProperty("synth")){if(t.isBus||!isSynth(t.instrument)||!op["synth"].isObject())return fail("Synth overrides require an built-in synth track.");auto patch=synthPatchToJson(t.synth);for(const auto& field:op["synth"].getDynamicObject()->getProperties()){if(!patch.hasProperty(field.name))return fail("Unknown synth parameter: "+field.name.toString());patch.getDynamicObject()->setProperty(field.name,field.value);}auto valid=synthPatchFromJson(patch,t.synth,true,true,true);if(valid.failed())return valid;t.soundName="Custom MCP sound";}
    if(op.hasProperty("tuning")){if(t.isBus)return fail("Buses do not have pitched sources.");auto valid=microTuningFromJson(op["tuning"],t.tuning);if(valid.failed())return valid;}
    if(op.hasProperty("params")){auto p=op["params"];if(!keys(p,{"volume","pan","cutoff","drive","send","attack","release","sampleRoot","sampleTune"}))return fail("Unknown track parameter.");
        if(p.hasProperty("sampleRoot")){if(!number(p["sampleRoot"],0,127,true))return fail("Invalid sampler root.");t.sampleRoot=(int)p["sampleRoot"];}if(p.hasProperty("sampleTune")){if(!number(p["sampleTune"],-100,100))return fail("Invalid sampler fine tune.");t.sampleTune=(double)p["sampleTune"];}
        struct Setting{const char* name;float* value;double low,high;};for(auto s:{Setting{"volume",&t.volume,0,1.5},{"pan",&t.pan,-1,1},{"cutoff",&t.cutoff,60,20000},{"drive",&t.drive,0,1},{"send",&t.send,0,.8},{"attack",&t.attack,.001,2},{"release",&t.release,.02,3}})if(p.hasProperty(s.name)){if(!number(p[s.name],s.low,s.high))return fail("Invalid track parameter: "+String(s.name));*s.value=(float)(double)p[s.name];}}
    if(op.hasProperty("effects")){auto valid=effectSettings(op["effects"],t.mixer);if(valid.failed())return valid;}
    if(op.hasProperty("output")){if(!number(op["output"],-1,maxTracks-1,true))return fail("Invalid output bus index.");t.mixer.output=(int)op["output"];}
    return Result::ok();
}
